// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.capture/** * NOUS — AI Noise Suppressor (RNNoise wrapper). * * Layer 2 of the audio capture pipeline. Removes background noise — traffic, * fans, keyboards, wind — while keeping speech crystal clear. The reference * implementation runs a 2 MB TFLite model (RNNoise) via NNAPI for hardware * acceleration; tests inject a fake. * * ## Performance budget * * Per the v2 strategy doc §15: *  - Target: < 5 ms per 20 ms chunk (we must process faster than realtime). *  - Runs on NPU/GPU via NNAPI when available. * * ## Audio format * *  - 16 kHz sample rate *  - 16-bit signed PCM *  - Mono *  - 20 ms chunks = 320 samples per call to [suppress] * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline — RNNoise Integration</a> */sealed interface NoiseSuppressor {    /**     * Suppress noise from one audio chunk.     *     * @param input raw audio (16 kHz, 16-bit, 320 samples = 20 ms).     * @return clean audio (same format & length, background noise removed).     */    fun suppress(input: ShortArray): ShortArray    /** Whether the underlying model is loaded and ready. */    val isReady: Boolean    /** Release native resources. Idempotent. */    fun release()    // ──────────────────────────────────────────────────────────────────────    /**     * No-op suppressor — passes audio through unchanged.     *     * Used as a default when no TFLite model is downloaded yet, or in tests     * that don't exercise noise suppression.     */    class Noop : NoiseSuppressor {        override fun suppress(input: ShortArray): ShortArray = input        override val isReady: Boolean = true        override fun release() = Unit    }    // ──────────────────────────────────────────────────────────────────────    /**     * Spectral-mask style suppressor backed by a TFLite model.     *     * The real implementation loads `rnnoise.tflite` (~2 MB) and runs it via     * NNAPI. This class is a thin Kotlin wrapper — the heavy lifting happens     * in :native:rnnoise (JNI). The wrapper is here so the pipeline can be     * assembled without the native lib during early development, and so     * instrumentation tests can exercise the wiring.     *     * @param modelPath absolute path to `rnnoise.tflite`.     */    class TFLite(        private val modelPath: String,        private val backend: Backend = Backend.NNAPI,    ) : NoiseSuppressor {        /** NNAPI delegate target. */        enum class Backend { NNAPI, GPU, CPU }        // Loaded lazily so the pipeline can be constructed on the main thread        // without blocking — the actual Interpreter creation happens on the        // audio dispatcher the first time [suppress] is called.        private val loaded: Boolean by lazy { loadModel(modelPath, backend) }        override val isReady: Boolean get() = loaded        override fun suppress(input: ShortArray): ShortArray {            require(input.size == CHUNK_SAMPLES) {                "RNNoise expects $CHUNK_SAMPLES samples (20 ms @ 16 kHz), got ${input.size}"            }            if (!loaded) return input  // graceful degrade — don't crash the mic loop            // 1. Convert PCM → bark-scale spectrogram features.            val features = extractBarkFeatures(input)            // 2. Run TFLite inference → spectral mask.            val mask = runInference(features)            // 3. Apply mask to original STFT and convert back to PCM.            return applyMask(input, mask)        }        override fun release() {            // Real impl closes the TFLite Interpreter here.        }        // ─── Native-bridge hooks (real impl lives in :native:rnnoise) ──────        private fun loadModel(path: String, backend: Backend): Boolean {            // JNI call: rnnoise_load(path, backend.ordinal)            // Returns true on success. Returns false (and logs) if the model            // file is missing — pipeline will use Noop behavior in that case.            return false  // disabled until :native:rnnoise ships (Module 5 Year-2)        }        private fun extractBarkFeatures(input: ShortArray): FloatArray {            // STFT + bark-scale filterbank. Real impl in :native:rnnoise.            return FloatArray(FEATURE_SIZE)        }        private fun runInference(features: FloatArray): FloatArray {            // TFLite Interpreter.run() with NNAPI delegate. Real impl in :native:rnnoise.            return FloatArray(MASK_SIZE)        }        private fun applyMask(input: ShortArray, mask: FloatArray): ShortArray {            // ISTFT with gain mask applied. Real impl in :native:rnnoise.            return input.copyOf()        }        companion object {            /** 20 ms @ 16 kHz = 320 samples per chunk. */            const val CHUNK_SAMPLES = 320            /** Bark-scale feature vector size (RNNoise uses 22 bands × frames). */            const val FEATURE_SIZE = 22 * 8            /** Spectral mask size (one gain per bark band per frame). */            const val MASK_SIZE = 22 * 8        }    }}